package com.abhishek.ecommerce.product;
import jakarta.validation.Valid;import jakarta.validation.constraints.*;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;import org.springframework.transaction.annotation.Transactional;import java.math.BigDecimal;import java.util.*;
@RestController @RequestMapping("/api/products") public class ProductController{record ProductRequest(@NotBlank String sku,@NotBlank String name,String category,@NotNull @Positive BigDecimal price,@Min(0)int stock){}final ProductRepository repo;ProductController(ProductRepository r){repo=r;}@GetMapping List<Product>all(@RequestParam(required=false)String category){return category==null?repo.findByActiveTrue():repo.findByCategoryAndActiveTrue(category);}@GetMapping("/{id}")Product one(@PathVariable UUID id){return repo.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Product not found"));}@PostMapping ResponseEntity<Product>create(@Valid @RequestBody ProductRequest x){Product p=new Product();p.setSku(x.sku());p.setName(x.name());p.setCategory(x.category());p.setPrice(x.price());p.setStock(x.stock());return ResponseEntity.status(201).body(repo.save(p));}@PutMapping("/{id}")Product update(@PathVariable UUID id,@Valid @RequestBody ProductRequest x){Product p=one(id);p.setSku(x.sku());p.setName(x.name());p.setCategory(x.category());p.setPrice(x.price());p.setStock(x.stock());return repo.save(p);}@DeleteMapping("/{id}")ResponseEntity<Void>delete(@PathVariable UUID id){Product p=one(id);p.setActive(false);repo.save(p);return ResponseEntity.noContent().build();}@PostMapping("/{id}/reserve")@Transactional Product reserve(@PathVariable UUID id,@RequestParam @Min(1)int quantity){Product p=one(id);if(p.getStock()<quantity)throw new ResponseStatusException(HttpStatus.CONFLICT,"Insufficient stock");p.setStock(p.getStock()-quantity);return repo.save(p);}@PostMapping("/{id}/release")@Transactional Product release(@PathVariable UUID id,@RequestParam @Min(1)int quantity){Product p=one(id);p.setStock(p.getStock()+quantity);return repo.save(p);}}